import json
from urllib.parse import urlparse, parse_qs

# Test various scenarios
tests = [
    ('POST /books', {'title': '1984', 'author': 'Orwell', 'isbn': '123456'}),
    ('POST /books', {'title': 123, 'author': 'Orwell', 'isbn': '123456'}),
    ('POST /books', {'title': '1984', 'author': None, 'isbn': '123456'}),
    ('POST /books', {'title': '1984', 'author': 'Orwell', 'isbn': None}),
    ('POST /books', {'title': '1984', 'author': 'Orwell', 'isbn': 123456}),
    ('POST /books', {'title': '', 'author': 'Orwell', 'isbn': '123456'}),
    ('POST /books', {'title': '1984', 'author': 'Orwell', 'isbn': ''}),
    ('POST /books', {'title': '1984', 'author': 'Orwell', 'isbn': 123456}),
    ('POST /books', {'synopsis': null}),
    ('POST /books', {'synopsis': 123}),
    ('POST /books', {}),
    ('POST /books', {'title': '1984'}),
    ('POST /books', {'title': '1984', 'author': 'Orwell', 'isbn': '123456', 'id': 1}),
    ('POST /books', {'title': '1984', 'author': 'Orwell', 'isbn': '123456', 'id': 1}),
]

for path, body in tests:
    # Simulate what do_POST does
    if 'POST' in path:
        try:
            data = json.loads(body)
            if isinstance(data, dict) and 'id' not in data:
                title = data.get('title')
                author = data.get('author')
                isbn = data.get('isbn')
                synopsis = data.get('synopsis', '')
                # Check for AttributeError on .strip()
                if title is not None and hasattr(title, 'strip') and not isinstance(title, str):
                    print(f'{path}: WOULD CRASH - title not str but has .strip() method: {type(title)}')
                elif title is None:
                    print(f'{path}: title is None -> .strip() would fail')
                elif not isinstance(title, str):
                    print(f'{path}: title is {type(title).__name__} (wrong type)')
                elif not title.strip():
                    print(f'{path}: title strip is empty: {repr(title)}')
                elif author is not None and not isinstance(author, str):
                    print(f'{path}: author is {type(author).__name__} (wrong type)')
                elif author is None:
                    print(f'{path}: author is None -> .strip() would fail')
                elif not author.strip():
                    print(f'{path}: author strip is empty: {repr(author)}')
                elif isbn is not None and not isinstance(isbn, str):
                    print(f'{path}: isbn is {type(isbn).__name__} (wrong type)')
                elif isbn is None:
                    print(f'{path}: isbn is None -> .strip() would fail')
                elif not isbn.strip():
                    print(f'{path}: isbn strip is empty: {repr(isbn)}')
                elif synopsis is not None and not isinstance(synopsis, str):
                    print(f'{path}: synopsis is {type(synopsis).__name__} (wrong type)')
                else:
                    print(f'{path}: OK')
            else:
                print(f'{path}: invalid (not dict or has id)')
        except json.JSONDecodeError:
            print(f'{path}: invalid JSON')
    else:
        print(f'{path}: not POST')
"

